//! Leopard-RS style Reed–Solomon over GF(2^16), backed by the
//! `reed-solomon-simd` crate.
//!
//! Notes on this backend's shape:
//!
//! - The decoder restores *original* shards only. Missing parity shards are
//!   regenerated by re-encoding after the originals are restored.
//! - Encoder and decoder objects hold working memory and are created per
//!   call here. If this backend is selected after Phase 0 measurements, the
//!   objects should be pooled and reset instead.
//! - The crate documents that shard sizes that are multiples of 64 bytes
//!   encode identically across all its versions; we require that alignment.

use reed_solomon_simd::{ReedSolomonDecoder, ReedSolomonEncoder};

use crate::coder::{check_encode_shape, check_reconstruct_shape};
use crate::{CodeParams, EcError, ErasureCoder, SchemeId};

/// Shard alignment for this backend.
pub const ALIGNMENT: usize = 64;

/// Leopard-RS backend.
#[derive(Debug, Clone)]
pub struct LeopardRs {
    params: CodeParams,
}

impl LeopardRs {
    /// Create a coder.
    ///
    /// # Errors
    ///
    /// Returns [`EcError::InvalidParams`] when the counts are outside the
    /// backend's supported range.
    pub fn new(params: CodeParams) -> Result<Self, EcError> {
        params.validate_for(SchemeId::ReedSolomonLeopardGf16V1)?;
        // Probe the backend once so that unsupported combinations fail early.
        ReedSolomonEncoder::new(params.data, params.parity, ALIGNMENT)
            .map_err(|e| EcError::InvalidParams(e.to_string()))?;
        Ok(Self { params })
    }

    fn encode_into(
        &self,
        data: &[&[u8]],
        parity: &mut [&mut [u8]],
        len: usize,
    ) -> Result<(), EcError> {
        let mut enc = ReedSolomonEncoder::new(self.params.data, self.params.parity, len)
            .map_err(|e| EcError::Backend(e.to_string()))?;
        for d in data {
            enc.add_original_shard(d)
                .map_err(|e| EcError::Backend(e.to_string()))?;
        }
        let result = enc.encode().map_err(|e| EcError::Backend(e.to_string()))?;
        for (dst, src) in parity.iter_mut().zip(result.recovery_iter()) {
            dst.copy_from_slice(src);
        }
        Ok(())
    }
}

impl ErasureCoder for LeopardRs {
    fn scheme(&self) -> SchemeId {
        SchemeId::ReedSolomonLeopardGf16V1
    }

    fn params(&self) -> CodeParams {
        self.params
    }

    fn shard_alignment(&self) -> usize {
        ALIGNMENT
    }

    fn encode(&self, data: &[&[u8]], parity: &mut [&mut [u8]]) -> Result<(), EcError> {
        let len = check_encode_shape(self.params, ALIGNMENT, data, parity)?;
        self.encode_into(data, parity, len)
    }

    fn reconstruct(&self, shards: &mut [Option<Vec<u8>>]) -> Result<(), EcError> {
        let (len, present) = check_reconstruct_shape(self.params, ALIGNMENT, shards)?;
        if present == self.params.total() {
            return Ok(());
        }
        let k = self.params.data;

        // Restore missing originals. Feed every present shard; the backend
        // decides which it needs.
        let missing_data = shards[..k].iter().any(Option::is_none);
        let mut restored_data: Vec<(usize, Vec<u8>)> = Vec::new();
        if missing_data {
            let mut dec = ReedSolomonDecoder::new(k, self.params.parity, len)
                .map_err(|e| EcError::Backend(e.to_string()))?;
            let mut fed = 0;
            for (i, s) in shards.iter().enumerate() {
                if let Some(s) = s {
                    if fed >= k {
                        break;
                    }
                    if i < k {
                        dec.add_original_shard(i, s)
                    } else {
                        dec.add_recovery_shard(i - k, s)
                    }
                    .map_err(|e| EcError::Backend(e.to_string()))?;
                    fed += 1;
                }
            }
            let result = dec.decode().map_err(|e| EcError::Backend(e.to_string()))?;
            for (i, s) in result.restored_original_iter() {
                restored_data.push((i, s.to_vec()));
            }
        }

        // Nothing is written back until the backend has succeeded.
        for (i, s) in restored_data {
            shards[i] = Some(s);
        }

        // Regenerate missing parity, if any, from the now-complete data.
        if shards[k..].iter().any(Option::is_none) {
            let data: Vec<&[u8]> = shards[..k]
                .iter()
                .map(|s| s.as_deref().expect("data complete after decode"))
                .collect();
            let mut parity_bufs: Vec<Vec<u8>> = vec![vec![0u8; len]; self.params.parity];
            {
                let mut parity: Vec<&mut [u8]> =
                    parity_bufs.iter_mut().map(Vec::as_mut_slice).collect();
                self.encode_into(&data, &mut parity, len)?;
            }
            for (slot, buf) in shards[k..].iter_mut().zip(parity_bufs) {
                if slot.is_none() {
                    *slot = Some(buf);
                }
            }
        }
        Ok(())
    }
}
